import { ImageFormat, Permission, Role } from '@appwrite.io/console'
import { sdk } from '@/lib/appwrite/sdk'

export const APPS_LOGO_BUCKET_ID = 'appAssets'
export const APPS_LOGO_DEFAULT_CONSOLE_REGION = 'fra'

/** Legacy bucket id still present in older logoUri values. */
const APPS_LOGO_LEGACY_BUCKET_ID = 'apps'

export function resolveAppsLogoConsoleRegion(
  region?: string | null,
): string {
  if (
    typeof region === 'string' &&
    region.trim() &&
    region.trim().toLowerCase() !== 'unknown'
  ) {
    return region.trim().toLowerCase().replace(/\s+/g, '')
  }
  return APPS_LOGO_DEFAULT_CONSOLE_REGION
}

export function getAppsLogoConsoleStorageSdk(region?: string | null) {
  return sdk.forConsoleIn(resolveAppsLogoConsoleRegion(region))
}

export function buildAppLogoFilePermissions(teamId: string): string[] {
  return [
    Permission.read(Role.any()),
    Permission.write(Role.team(teamId)),
  ]
}

export function getAppLogoFilePreviewUrl(
  fileId: string,
  options?: {
    width?: number
    height?: number
    output?: ImageFormat
    region?: string | null
  },
): string {
  const consoleSdk = getAppsLogoConsoleStorageSdk(options?.region)
  return consoleSdk.storage.getFilePreview({
    bucketId: APPS_LOGO_BUCKET_ID,
    fileId,
    width: options?.width ?? 256,
    height: options?.height ?? 256,
    output: options?.output,
  })
}

const APPS_LOGO_FILE_ID_PATTERN =
  /\/storage\/buckets\/(?:appAssets|apps)\/files\/([^/?#]+)\/(?:preview|view|download)/i

export function parseAppLogoFileId(logoUri: string): string | null {
  const trimmed = logoUri.trim()
  if (!trimmed) return null

  const match = trimmed.match(APPS_LOGO_FILE_ID_PATTERN)
  return match?.[1] ?? null
}

export function isAppLogoStorageUrl(logoUri: string): boolean {
  return parseAppLogoFileId(logoUri) !== null
}

export function resolveAppLogoDisplayUrl(
  logoUri: string | null | undefined,
  options?: {
    width?: number
    height?: number
    region?: string | null
  },
): string | null {
  const trimmed = logoUri?.trim()
  if (!trimmed) return null

  const fileId = parseAppLogoFileId(trimmed)
  if (fileId) {
    return getAppLogoFilePreviewUrl(fileId, options)
  }

  // Keep external URLs and any non-storage values as-is.
  if (trimmed.includes(`/${APPS_LOGO_LEGACY_BUCKET_ID}/`)) {
    return trimmed
  }

  return trimmed
}
import {
  PUBLIC_CATALOG_LOGO_COLOR_CLASSES,
  PUBLIC_CATALOG_LOGO_IMAGE_CLASSES,
} from '@/lib/public-icon-classes'
import { cn } from '@/lib/utils'

export const MARKETPLACE_APP_LOGO_SIZE_CLASSNAMES = {
  sm: 'h-8 w-8 rounded-lg p-1.5',
  md: 'h-10 w-10 rounded-lg p-2',
  lg: 'h-12 w-12 rounded-xl p-2.5',
  consent: 'h-16 w-16 rounded-xl p-3',
  xl: 'h-20 w-20 rounded-xl p-4',
} as const

export type MarketplaceAppLogoSize = keyof typeof MARKETPLACE_APP_LOGO_SIZE_CLASSNAMES

const SIZE_CLASSNAMES = MARKETPLACE_APP_LOGO_SIZE_CLASSNAMES

type MarketplaceAppLogoProps = {
  src: string
  size?: MarketplaceAppLogoSize
  className?: string
  alt?: string
  /** When the primary `src` fails to load (e.g. missing OAuth provider icon). */
  fallbackSrc?: string
  onImageError?: () => void
  /**
   * Official marketplace catalog artwork uses grayscale + invert. User-published
   * app logos render in full color on consent and My apps.
   */
  monochrome?: boolean
}

/**
 * Catalog logos are black artwork on a transparent background; uploaded
 * logos may be colorful, so grayscale forces everything monochrome. The
 * partial invert remaps black artwork onto the theme's muted-foreground
 * gray (and flips it light in dark mode) so tiles match the category-icon
 * fallback contrast instead of sitting at full black/white.
 */
export function MarketplaceAppLogo({
  src,
  size = 'md',
  className,
  alt = '',
  fallbackSrc,
  onImageError,
  monochrome = true,
}: MarketplaceAppLogoProps) {
  return (
    <div
      className={cn(
        'flex shrink-0 items-center justify-center border border-border/60 bg-muted',
        SIZE_CLASSNAMES[size],
        className,
      )}
    >
      <img
        src={src}
        alt={alt}
        decoding="async"
        className={
          monochrome
            ? PUBLIC_CATALOG_LOGO_IMAGE_CLASSES
            : PUBLIC_CATALOG_LOGO_COLOR_CLASSES
        }
        onError={(e) => {
          onImageError?.()
          if (!fallbackSrc) return
          const img = e.currentTarget
          if (img.dataset.fallbackApplied === 'true') return
          img.dataset.fallbackApplied = 'true'
          img.src = fallbackSrc
        }}
      />
    </div>
  )
}
